WITH focal AS (SELECT REPLACE(id_imovel,'-','') id_car_norm FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE id_imovel='BA-2929701-3438EBE3EC1C4160B13A7DC99112E048' AND data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),prop AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm,cpf,cnpj_basico FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2019 AND 2024 AND id_car IS NOT NULL AND TRIM(id_car)!=''),fp AS (SELECT * FROM prop JOIN focal USING(id_car_norm)),mut AS (SELECT id_referencia_bacen,STRING_AGG(DISTINCT CASE WHEN cpf IS NOT NULL AND cpf!='' THEN CONCAT('M_',SUBSTR(TO_HEX(SHA256(cpf)),1,10)) WHEN cnpj IS NOT NULL AND cnpj!='' THEN CONCAT('M_',SUBSTR(TO_HEX(SHA256(cnpj)),1,10)) END,', ') mutuarios_anon FROM `basedosdados.br_bcb_sicor.recurso_publico_mutuario` WHERE ano_emissao BETWEEN 2019 AND 2024 GROUP BY id_referencia_bacen),lib AS (SELECT id_referencia_bacen,numero_ordem,SUM(valor_liberado) valor_liberado,MIN(data_liberacao) primeira_liberacao,MAX(data_liberacao) ultima_liberacao,COUNT(*) parcelas_liberacao FROM `basedosdados.br_bcb_sicor.liberacao` WHERE ano BETWEEN 2019 AND 2024 AND mes BETWEEN 1 AND 12 GROUP BY 1,2),ag AS (SELECT id_referencia_bacen,STRING_AGG(DISTINCT CONCAT('AG_',SUBSTR(TO_HEX(SHA256(cnpj_agencia)),1,10)),', ') agencias_anon,STRING_AGG(DISTINCT numero_cedula,', ') numeros_cedula FROM `basedosdados.br_bcb_sicor.recurso_publico_complemento_operacao` WHERE ano_emissao BETWEEN 2019 AND 2024 GROUP BY id_referencia_bacen),dp AS (SELECT DISTINCT chave,valor FROM `basedosdados.br_bcb_sicor.dicionario` WHERE nome_coluna='id_programa') SELECT op.ano_emissao,op.id_referencia_bacen,op.numero_ordem,op.data_emissao,STRING_AGG(DISTINCT CASE WHEN fp.cpf IS NOT NULL AND fp.cpf!='' THEN CONCAT('P_',SUBSTR(TO_HEX(SHA256(fp.cpf)),1,10)) WHEN fp.cnpj_basico IS NOT NULL AND fp.cnpj_basico!='' THEN CONCAT('P_',SUBSTR(TO_HEX(SHA256(fp.cnpj_basico)),1,10)) END,', ') proprietarios_anon,COALESCE(mut.mutuarios_anon,'(sem registro)') mutuarios_anon,op.valor_parcela_credito valor_original,lib.valor_liberado,lib.primeira_liberacao,lib.ultima_liberacao,lib.parcelas_liberacao,op.area_financiada,op.id_empreendimento,e.produto,e.finalidade,COALESCE(dp.valor,CONCAT('código ',op.id_programa)) programa,i.nome instituicao,COALESCE(ag.agencias_anon,'(sem agência)') agencias_anon,ag.numeros_cedula FROM fp JOIN `basedosdados.br_bcb_sicor.operacao` op USING(ano_emissao,id_referencia_bacen,numero_ordem) LEFT JOIN mut USING(id_referencia_bacen) LEFT JOIN lib USING(id_referencia_bacen,numero_ordem) LEFT JOIN ag USING(id_referencia_bacen) LEFT JOIN `basedosdados.br_bcb_sicor.empreendimento` e USING(id_empreendimento) LEFT JOIN dp ON dp.chave=op.id_programa LEFT JOIN `basedosdados.br_bcb_sicor.instituicao_financeira` i ON i.cnpj_basico=op.cnpj_basico_instituicao_financeira GROUP BY 1,2,3,4,mut.mutuarios_anon,op.valor_parcela_credito,lib.valor_liberado,lib.primeira_liberacao,lib.ultima_liberacao,lib.parcelas_liberacao,op.area_financiada,op.id_empreendimento,e.produto,e.finalidade,dp.valor,op.id_programa,i.nome,ag.agencias_anon,ag.numeros_cedula ORDER BY op.data_emissao,op.id_referencia_bacen,op.numero_ordem